INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2010 - Year in Review', 'اقتصاد اليمن 2010 - مراجعة السنة', 'The year 2010 served as a pre-crisis baseline for Yemen, characterized by robust economic growth and simmering political and humanitarian challenges. Economically, the country experienced a strong real GDP growth of 7.7%, primarily driven by the coming online of the Yemen LNG project and high oil prices, despite a high inflation rate of 11.2%. Politically, the year began with the formal end of the Sixth Sa''ada War against the Houthis in February, though the government continued to face a growing threat from Al-Qaeda in the Arabian Peninsula (AQAP) and underlying political instability. The humanitarian situation remained precarious, with 7.5 million people (32.1% of the population) classified as food insecure, and up to 300,000 internally displaced persons (IDPs) from the northern conflict requiring aid.', 'The year 2010 served as a pre-crisis baseline for Yemen, characterized by robust economic growth and simmering political and humanitarian challenges. Economically, the country experienced a strong real GDP growth of 7.7%, primarily driven by the coming online of the Yemen LNG project and high oil prices, despite a high inflation rate of 11.2%. Politically, the year began with the formal end of the Sixth Sa''ada War against the Houthis in February, though the government continued to face a growing threat from Al-Qaeda in the Arabian Peninsula (AQAP) and underlying political instability. The humanitarian situation remained precarious, with 7.5 million people (32.1% of the population) classified as food insecure, and up to 300,000 internally displaced persons (IDPs) from the northern conflict requiring aid.', '2010-12-31', 'economic', 'high', 'IMF Staff Report 2010, UN OCHA FTS, WFP, IRIN, FAO, FRED St. Louis', 'year-2010,annual-review');

