INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2011 - Year in Review', 'اقتصاد اليمن 2011 - مراجعة السنة', 'The year 2011 was defined by the Yemeni Revolution, a wave of Arab Spring protests that led to widespread political turmoil and a severe economic contraction. The protests and associated conflict, including attacks on critical infrastructure like oil pipelines, caused a sharp decline in real GDP by 12.7% and fueled an inflation rate of 19.54%. The political crisis culminated in the signing of the Gulf Cooperation Council (GCC) Initiative in November, which established a framework for a political transition. Concurrently, the humanitarian situation deteriorated significantly, with 10.6 million people becoming food-insecure and tens of thousands displaced by fighting, particularly in the Abyan Governorate.', 'The year 2011 was defined by the Yemeni Revolution, a wave of Arab Spring protests that led to widespread political turmoil and a severe economic contraction. The protests and associated conflict, including attacks on critical infrastructure like oil pipelines, caused a sharp decline in real GDP by 12.7% and fueled an inflation rate of 19.54%. The political crisis culminated in the signing of the Gulf Cooperation Council (GCC) Initiative in November, which established a framework for a political transition. Concurrently, the humanitarian situation deteriorated significantly, with 10.6 million people becoming food-insecure and tens of thousands displaced by fighting, particularly in the Abyan Governorate.', '2011-12-31', 'economic', 'high', 'World Bank, IMF, Macrotrends, US Treasury, UN OCHA, ConstitutionNet, Sana''a Center, ReliefWeb, UN News, CS Monitor, Washington Post', 'year-2011,annual-review');

