INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2012 - Year in Review', 'اقتصاد اليمن 2012 - مراجعة السنة', 'The year 2012 marked the formal political transition in Yemen, with the unopposed election of Abdrabbuh Mansur Hadi as President in February, ending the 33-year rule of Ali Abdullah Saleh under the GCC Initiative. Economically, the country began a fragile recovery from the 2011 crisis, with real GDP growth estimated at 1.4%, though political and security upheaval continued to decelerate progress. The government faced a significant fiscal challenge, with the deficit reaching 9.4% of GDP, partly due to large petroleum subsidies. The humanitarian situation remained dire, with approximately 10 million people food insecure and 385,000 internally displaced persons, necessitating a UN Humanitarian Response Plan that was 55.7% funded.', 'The year 2012 marked the formal political transition in Yemen, with the unopposed election of Abdrabbuh Mansur Hadi as President in February, ending the 33-year rule of Ali Abdullah Saleh under the GCC Initiative. Economically, the country began a fragile recovery from the 2011 crisis, with real GDP growth estimated at 1.4%, though political and security upheaval continued to decelerate progress. The government faced a significant fiscal challenge, with the deficit reaching 9.4% of GDP, partly due to large petroleum subsidies. The humanitarian situation remained dire, with approximately 10 million people food insecure and 385,000 internally displaced persons, necessitating a UN Humanitarian Response Plan that was 55.7% funded.', '2012-12-31', 'economic', 'high', 'World Bank, International Monetary Fund (IMF), UN Office for the Coordination of Humanitarian Affairs (OCHA), Internal Displacement Monitoring Centre (IDMC), Macrotrends, PoundSterlingLive, FRED', 'year-2012,annual-review');

INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('GCC Initiative and Presidential Election', 'GCC Initiative and Presidential Election', 'GCC Initiative and Presidential Election led to Formal end of Saleh''s 33-year rule. Political Transition', 'GCC Initiative and Presidential Election led to Formal end of Saleh''s 33-year rule. Political Transition', '2012-06-30', 'political', 'medium', 'World Bank, International Monetary Fund (IMF), UN Office for the Coordination of Humanitarian Affairs (OCHA), Internal Displacement Monitoring Centre (IDMC), Macrotrends, PoundSterlingLive, FRED', 'year-2012,causation');

