INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2015 - Year in Review', 'اقتصاد اليمن 2015 - مراجعة السنة', 'The year 2015 was defined by the escalation of the Yemeni Civil War, marked by the launch of the Saudi-led "Operation Decisive Storm" in March, which transitioned into "Operation Restoring Hope" in April. This military intervention led to a severe economic contraction, with the GDP plummeting by nearly 28%, and triggered a massive humanitarian crisis. The internationally recognized government of President Hadi was forced to operate from Aden, while the Houthis maintained control over the capital, Sanaa, leading to a de facto political and economic split. The conflict and subsequent blockade severely disrupted trade, oil production, and state finances, pushing millions into acute food insecurity and displacing over two million people.', 'The year 2015 was defined by the escalation of the Yemeni Civil War, marked by the launch of the Saudi-led "Operation Decisive Storm" in March, which transitioned into "Operation Restoring Hope" in April. This military intervention led to a severe economic contraction, with the GDP plummeting by nearly 28%, and triggered a massive humanitarian crisis. The internationally recognized government of President Hadi was forced to operate from Aden, while the Houthis maintained control over the capital, Sanaa, leading to a de facto political and economic split. The conflict and subsequent blockade severely disrupted trade, oil production, and state finances, pushing millions into acute food insecurity and displacing over two million people.', '2015-12-31', 'economic', 'high', 'Macrotrends, IndexMundi, Exchange-Rates.org, UN OCHA, World Bank, IMF, Wikipedia, Britannica, Council on Foreign Relations, IOM', 'year-2015,annual-review');

