INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2016 - Year in Review', 'اقتصاد اليمن 2016 - مراجعة السنة', 'The year 2016 was defined by the catastrophic **split of the Central Bank of Yemen (CBY)** in September, when the internationally recognized government relocated its headquarters from Sana''a to Aden, effectively fragmenting the country''s financial system. This move immediately triggered a severe liquidity crisis and the cessation of civil servant salary payments in Houthi-controlled areas, deepening the economic war. The conflict and financial collapse led to a **real GDP contraction of -9.38%** and an annual inflation rate of 21.30%. The humanitarian crisis intensified, with **14.4 million people facing food insecurity**, underscoring the direct link between the political conflict and the economic and humanitarian catastrophe.', 'The year 2016 was defined by the catastrophic **split of the Central Bank of Yemen (CBY)** in September, when the internationally recognized government relocated its headquarters from Sana''a to Aden, effectively fragmenting the country''s financial system. This move immediately triggered a severe liquidity crisis and the cessation of civil servant salary payments in Houthi-controlled areas, deepening the economic war. The conflict and financial collapse led to a **real GDP contraction of -9.38%** and an annual inflation rate of 21.30%. The humanitarian crisis intensified, with **14.4 million people facing food insecurity**, underscoring the direct link between the political conflict and the economic and humanitarian catastrophe.', '2016-12-31', 'economic', 'high', 'World Bank, IMF, UN OCHA, CEIC Data, Macrotrends, Al Jazeera, Sana''a Center for Strategic Studies, ReliefWeb', 'year-2016,annual-review');

