INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2017 - Year in Review', 'اقتصاد اليمن 2017 - مراجعة السنة', 'The year 2017 was defined by a severe escalation of the humanitarian crisis, primarily driven by the Saudi-led coalition''s total blockade in November and the world''s largest recorded cholera outbreak, which surpassed one million suspected cases. Economically, the country saw a continued contraction of real GDP by an estimated 5.9%, coupled with a sharp rise in inflation to 24.5%. The ongoing conflict and the split of the Central Bank of Yemen led to a significant divergence between the official (250 YER/USD) and parallel exchange rates, further crippling the economy and exacerbating food insecurity for 17 million people. The blockade severely restricted the flow of essential goods, pushing the country closer to famine.', 'The year 2017 was defined by a severe escalation of the humanitarian crisis, primarily driven by the Saudi-led coalition''s total blockade in November and the world''s largest recorded cholera outbreak, which surpassed one million suspected cases. Economically, the country saw a continued contraction of real GDP by an estimated 5.9%, coupled with a sharp rise in inflation to 24.5%. The ongoing conflict and the split of the Central Bank of Yemen led to a significant divergence between the official (250 YER/USD) and parallel exchange rates, further crippling the economy and exacerbating food insecurity for 17 million people. The blockade severely restricted the flow of essential goods, pushing the country closer to famine.', '2017-12-31', 'economic', 'high', 'World Bank, IMF, UN OCHA FTS, IOM TFPM, OpenDataForAfrica, The Global Economy, ReliefWeb, CNN', 'year-2017,annual-review');

