INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2022 - Year in Review', 'اقتصاد اليمن 2022 - مراجعة السنة', 'The year 2022 was defined by a significant political and security shift, beginning with the formation of the Presidential Leadership Council (PLC) in April, which consolidated the internationally recognized government''s leadership. Concurrently, a UN-brokered truce, also starting in April, led to a substantial de-escalation of conflict, contributing to a modest 1.5% GDP growth. However, this positive economic momentum was severely undermined in the latter half of the year when Houthi attacks on oil ports halted oil exports, crippling the PLC''s primary source of revenue. The humanitarian crisis remained dire, with over 19 million people requiring food assistance, while the dual central bank system continued to drive extreme fragmentation in the currency market.', 'The year 2022 was defined by a significant political and security shift, beginning with the formation of the Presidential Leadership Council (PLC) in April, which consolidated the internationally recognized government''s leadership. Concurrently, a UN-brokered truce, also starting in April, led to a substantial de-escalation of conflict, contributing to a modest 1.5% GDP growth. However, this positive economic momentum was severely undermined in the latter half of the year when Houthi attacks on oil ports halted oil exports, crippling the PLC''s primary source of revenue. The humanitarian crisis remained dire, with over 19 million people requiring food assistance, while the dual central bank system continued to drive extreme fragmentation in the currency market.', '2022-12-31', 'economic', 'high', 'World Bank, IMF, UN OCHA, FEWS, ACAPS, Wikipedia', 'year-2022,annual-review');

INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('UN-brokered Truce (April 2022)', 'UN-brokered Truce (April 2022)', 'UN-brokered Truce (April 2022) led to Modest GDP Growth. 1.5%', 'UN-brokered Truce (April 2022) led to Modest GDP Growth. 1.5%', '2022-06-30', 'political', 'medium', 'World Bank, IMF, UN OCHA, FEWS, ACAPS, Wikipedia', 'year-2022,causation');

