INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2025 - Year in Review', 'اقتصاد اليمن 2025 - مراجعة السنة', 'Yemen''s economy remained under severe strain in 2025, marked by a projected real GDP contraction of 0.5% and inflation that surged above 35% by mid-year due to the rial''s 30% weakening. The political landscape remained stalled, with the peace process failing to advance and the continued impact of Houthi attacks on oil facilities halting exports. The humanitarian crisis deepened, with 19.5 million people in need and the YHNRP 2025 only 24% funded by November, forcing the IRG to adopt FX stabilization measures in August to ease currency pressures.', 'Yemen''s economy remained under severe strain in 2025, marked by a projected real GDP contraction of 0.5% and inflation that surged above 35% by mid-year due to the rial''s 30% weakening. The political landscape remained stalled, with the peace process failing to advance and the continued impact of Houthi attacks on oil facilities halting exports. The humanitarian crisis deepened, with 19.5 million people in need and the YHNRP 2025 only 24% funded by November, forcing the IRG to adopt FX stabilization measures in August to ease currency pressures.', '2025-12-31', 'economic', 'high', 'IMF, World Bank, UN OCHA, IOM DTM, IPC, Central Bank of Yemen (CBY), Trading Economics, Statista, Joint Data Center (JDC)', 'year-2025,annual-review');

